<script>(function(){
$(document).off('submit.ipdOtWorkflow','.ipd-ot-ajax-form').on('submit.ipdOtWorkflow','.ipd-ot-ajax-form',function(event){event.preventDefault();var form=this;var notice=$(form).find('.ipd-ot-form-notice');fetch(form.action,{method:'POST',body:new window.FormData(form),headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(response){return response.json().then(function(data){return{ok:response.ok,data:data};});}).then(function(result){var data=result.data||{};if(data.csrfName&&data.csrfHash){$(form).find('input[name="'+data.csrfName+'"]').val(data.csrfHash);}if(!result.ok||parseInt(data.update||0,10)!==1){notice.html('<div class="alert alert-danger py-2">'+$('<div>').text(data.error_text||'Unable to save.').html()+'</div>');return;}notice.html('<div class="alert alert-success py-2">'+$('<div>').text(data.error_text||'Saved.').html()+'</div>');if(form.dataset.refresh==='panel'&&window.refreshIpdOtPanel){window.refreshIpdOtPanel();}if(form.dataset.refresh==='queue'&&window.refreshIpdOtQueue){window.refreshIpdOtQueue();}}).catch(function(){notice.html('<div class="alert alert-danger py-2">Unable to save.</div>');});});
})();</script>